curl -s 'https://cointelegraph.com/rss' --max-time 10 | python3 -c '
import sys, json, xml.etree.ElementTree as ET, re
from datetime import datetime, timedelta, timezone

def strip_html(s):
    # Also decode HTML entities
    import html
    return html.unescape(re.sub("<[^>]*>", "", s).strip())

try:
    xml_data = sys.stdin.read()
    if not xml_data:
        print(json.dumps({"error": "No XML data received from curl."}), file=sys.stderr)
        sys.exit(1)

    root = ET.fromstring(xml_data)
    stories = []
    # Use timezone-aware datetime object for comparison
    one_day_ago = datetime.now(timezone.utc) - timedelta(days=1)

    for item in root.findall(".//channel/item"):
        if len(stories) >= 3:
            break

        pub_date_str = item.find("pubDate").text
        pub_date = None
        # Try parsing RFC-1123 format with timezone
        try:
            pub_date = datetime.strptime(pub_date_str, "%a, %d %b %Y %H:%M:%S %z")
        except ValueError:
            # Fallback for formats without a timezone, assuming UTC
            try:
                pub_date = datetime.strptime(pub_date_str, "%a, %d %b %Y %H:%M:%S GMT").replace(tzinfo=timezone.utc)
            except ValueError:
                # If parsing fails, skip this item
                continue

        if pub_date >= one_day_ago:
            description_text = strip_html(item.find("description").text)

            story = {
                "title": item.find("title").text,
                "source": "Cointelegraph",
                "source_url": item.find("link").text,
                "summary": description_text,
                "key_facts": []
            }
            stories.append(story)

    output = {
        "date": datetime.now(timezone.utc).strftime("%Y-%m-%d"),
        "stories": stories
    }

    print(json.dumps(output, indent=2))

except ET.ParseError as e:
    print(json.dumps({"error": "Failed to parse XML", "details": str(e)}), file=sys.stderr)
    sys.exit(1)
except Exception as e:
    print(json.dumps({"error": "An unexpected error occurred", "details": str(e)}), file=sys.stderr)
    sys.exit(1)
'

